import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Мониторинг и журнал событий","description":"","frontmatter":{"pageId":"admins/monitoring","contentRevision":1},"headers":[],"relativePath":"ru/admins/monitoring.md","filePath":"ru/admins/monitoring.md"}'),o={name:"ru/admins/monitoring.md"};function n(s,a,l,d,m,h){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="мониторинг-и-журнал-событии" tabindex="-1">Мониторинг и журнал событий <a class="header-anchor" href="#мониторинг-и-журнал-событии" aria-label="Permalink to &quot;Мониторинг и журнал событий&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>GET /health проверяет доступность процесса; /metrics предоставляет метрики. Настрой сетевое ограничение и сбор с доверенного узла. Административный /status даёт служебное состояние; журнал /actions помогает связать изменения с оператором.</p><p>SSE GET /api/admin/events использует идентификатор epoch:seq. Передай Last-Event-ID при переподключении. gap означает, что события потеряны из-за рестарта/переполнения: перечитай текущее состояние, не выводи его только из неполного feed. По умолчанию буфер 1000, ping каждые 15 секунд.</p><p>Следи за свободным диском, возрастом последней успешной копии, отказами входа, сохранений, доставок и долгими live-сессиями. Сигнал «процесс жив» не заменяет проверку чтения/записи колонии.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Feed намеренно не содержит приватный чат, кошельки, посылки и ещё не высадившиеся рейды. Не включай токены/полные сейвы в метрики и общие логи. /metrics публичен на уровне приложения — ограничивай доступ сетью.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./discord">Discord-бот</a></li><li><a href="./troubleshooting">Проблемы администратора</a></li><li><a href="./api">Справочник REST API</a></li></ul>',10)])])}const u=e(o,[["render",n]]);export{p as __pageData,u as default};
